\begin{remark}[Remark 3.5]
  \label{rem:dc-ch2-3-5}


  \dcref{ch2:3.5}
  In a coordinate frame $X_i=\partial/\partial x_i$, symmetry is equivalent to
  \[
    \nabla_{X_i}X_j-\nabla_{X_j}X_i=[X_i,X_j]=0,
    \qquad
    \Gamma_{ij}^k=\Gamma_{ji}^k.\tag{5'}
  \]
\end{remark}

